const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.Color(0x1a1a2e);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 8);
camera.lookAt(0, 1.0, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// ── Materials ─────────────────────────
const bodyMat = new THREE.MeshStandardMaterial({ color: 0x3a7bd9, roughness: 0.5 });
const headMat = new THREE.MeshStandardMaterial({ color: 0xf4a46d, roughness: 0.6 });
const limbMat = new THREE.MeshStandardMaterial({ color: 0x2d5f2f, roughness: 0.6 });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x8b4513, roughness: 0.7 });
const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
const beltMat = new THREE.MeshStandardMaterial({ color: 0x222222, roughness: 0.4 });

// ── Helper ───────────────────────────
function box(w, h, d) {
  return new THREE.Mesh(new THREE.BoxGeometry(w, h, d), bodyMat);
}

// ── Humanoid Figure ──────────────────
const figure = new THREE.Group();
const root = new THREE.Group();
figure.add(root);

// Torso
const torso = box(0.4, 0.55, 0.28);
torso.position.y = 1.15;
root.add(torso);

// Head
const head = new THREE.Mesh(new THREE.SphereGeometry(0.13, 8, 8), headMat);
head.position.y = 0.22;
torso.add(head);

// Belt / hip
const hip = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.08, 0.3), beltMat);
hip.position.y = -0.32;
root.add(hip);

// ── Limbs ───────────────────────────
function createLimbPair(upperLen, lowerLen, radius) {
  const upper = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, upperLen, 8), limbMat);
  const lower = new THREE.Mesh(new THREE.CylinderGeometry(radius, radius, lowerLen, 8), limbMat);
  const foot = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.06, 0.18), shoeMat);
  lower.add(foot);
  upper.add(lower);
  return { upper, lower };
}

const leftArm = createLimbPair(0.28, 0.26, 0.045);
const rightArm = createLimbPair(0.28, 0.26, 0.045);
const leftLeg = createLimbPair(0.38, 0.35, 0.06);
const rightLeg = createLimbPair(0.38, 0.35, 0.06);

leftArm.upper.position.set(-0.25, 0.2, 0);
rightArm.upper.position.set(0.25, 0.2, 0);
leftLeg.upper.position.set(-0.1, -0.32, 0);
rightLeg.upper.position.set(0.1, -0.32, 0);

// Pivot at shoulder/hip
leftArm.upper.position.set(0, 0, 0);
leftArm.lower.position.set(0, -0.28, 0);
rightArm.upper.position.set(0, 0, 0);
rightArm.lower.position.set(0, -0.28, 0);
leftLeg.upper.position.set(0, 0, 0);
leftLeg.lower.position.set(0, -0.38, 0);
rightLeg.upper.position.set(0, 0, 0);
rightLeg.lower.position.set(0, -0.38, 0);

root.add(leftArm.upper, rightArm.upper, leftLeg.upper, rightLeg.upper);

