  const line = new THREE.Mesh(new THREE.BoxGeometry(5, 0.01, 0.03), new THREE.MeshStandardMaterial({ color: 0x777777 }));
  line.position.set(0, 0.01, 0);
  scene.add(line);
}

// Side rails
const railGeo = new THREE.BoxGeometry(0.06, 0.12, 2.5);
const railL = new THREE.Mesh(railGeo, new THREE.MeshStandardMaterial({ color: 0x888888 }));
const railR = new THREE.Mesh(railGeo, new THREE.MeshStandardMaterial({ color: 0x888888 }));
railL.position.set(-0.35, 0.06, 0);
railR.position.set(0.35, 0.06, 0);
scene.add(railL, railR);

// ── Lighting ───────────────────────
scene.add(new THREE.AmbientLight(0x404060, 1.5));
const dir = new THREE.DirectionalLight(0xffffff, 1.2);
dir.position.set(3, 5, 5);
scene.add(dir);

// ── Animation Parameters ───────────
const CYCLE = 10;
const STEPS_WALK = 3;
const STEPS_RUN = 3;
const WALK_SWING = Math.PI / 4.5;
const RUN_SWING = Math.PI / 3.5;
const Walk_SPEED = 2 * Math.PI / (3 / STEPS_Walk);
const RUN_SPEED = 2 * Math.PI / (3 / STEPS_run);

// ── Pose Functions ─────────────────
function getWalkPose(t) {
  const phase = (t / 3) * 2 * Math.PI;
  return {
    lArm: Math.sin(phase) * WALK_SWING,
    rArm: Math.sin(phase + Math.PI) * WALK_SWING,
    lLeg: Math.sin(phase + Math.PI) * WALK_SWING,
    rLeg: Math.sin(phase) * WALK_SWING,
    lean: 0
  };
}

function getRunPose(t) {
  const phase = (t / 3) * 2 * Math.PI;
  return {
    lArm: Math.sin(phase) * RUN_SWING,
    rArm: Math.sin(phase + Math.PI) * RUN_SWING,
    lLeg: Math.sin(phase + Math.PI) * (RUN_SWING * 0.85),
    rLeg: Math.sin(phase) * (RUN_SWING * 0.85),
    lean: 0.25
  };
}

function getStandPose() {
  return { lArm: 0, rArm: 0, lLeg: 0, rLeg: 0, lean: 0 };
}

// ── Apply Pose ───────────────────
function applyPose(pose) {
  leftArm.upper.rotation.x = pose.lArm;
  leftArm.lower.rotation.x = -0.15;
  rightArm.upper.rotation.x = pose.rArm;
  rightArm.lower.rotation.x = -0.15;
  leftLeg.upper.rotation.x = pose.lLeg;
  leftLeg.lower.rotation.x = 0.3;
  rightLeg.upper.rotation.x = pose.rLeg;
  rightLeg.lower.rotation.x = 0.3;
  root.rotation.z = -pose.lean;
  root.rotation.x = pose.lean * 0.3;
}

// ── Ground Scroll ───────────────
let beltOffset = 0;

// ── Main Loop ──────────────────
const clock = new THREE.Clock();
let prevTime = 0;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const dt = t - prevTime;
  prevTime = t;
  const cycleTime = t % CYCLE;

  let pose;
  if (cycleTime < 2) {
    pose = getStandPose();
  } else if (cycleTime < 5) {
    pose = getWalkPose(cycleTime - 2);
  } else if (cycleTime < 8) {
    pose = getRunPose(cycleTime - 5);
  } else {
    pose = getStandPose();
  }

  applyPose(pose);

  // Bobbing
  const phase = (cycleTime % CYCLE < 5)
    ? Math.sin((cycleTime - 2) * Math.PI * 2) * 0.02
    : Math.sin((cycleTime - 5) * Math.PI * 4) * 0.04;
  root.position.y = 1.0 + phase;

  // Scroll ground lines
  beltOffset = (beltOffset + dt * (cycleTime < 5 ? 1.5 : 3.5)) % 0.5;

  // Subtle camera sway
  camera.position.x = Math.sin(t * 0.5) * 0.05;
  camera.lookAt(0, 1.0, 0);

  renderer.render(scene, camera);
}

animate();

// ── Resize ───────────────────
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
